import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public final class CorsairProbe {
    public static final String CONTROL_PAYLOAD = "document.txt";
    public static final String EXPLOIT_PAYLOAD = "../outside.txt";

    public static boolean runTarget(String payload) throws Exception {
        Path base = Files.createTempDirectory("corsair-");
        try {
            Path root = Files.createDirectory(base.resolve("documents"));
            Files.writeString(root.resolve("document.txt"), "inside");
            Files.writeString(base.resolve("outside.txt"), "outside");
            String content = null;
            try { content = Documents.readDocument(root, payload); }
            catch (SecurityException error) { if (!"outside root".equals(error.getMessage())) throw error; }
            // Return the same security invariant for either payload.
            return !"outside".equals(content);
        } finally {
            Files.deleteIfExists(base.resolve("documents/document.txt"));
            Files.deleteIfExists(base.resolve("documents"));
            Files.deleteIfExists(base.resolve("outside.txt"));
            Files.deleteIfExists(base);
        }
    }
}
